import { assertEquals } from "jsr:@std/assert@1";
import { loadConfig } from "./loader.ts";

Deno.test("loadConfig works without .env.local", async () => {
  const dir = await Deno.makeTempDir();
  await Deno.writeTextFile(`${dir}/.env`, "PORT=9000\nDATABASE_URL=postgres://localhost/app\n");
  const cwd = Deno.cwd();
  Deno.chdir(dir);
